def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out."""
    # Simple approach: find first difference and determine what needs to change
    if s_in == s_out:
        return "", "", -1

    # Find first position where they differ
    pos = -1
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # One string is prefix of other
        if len(s_in) < len(s_out):
            return "", s_out[len(s_in):], len(s_in)
        else:
            return s_in[len(s_out):], "", len(s_out)

    # For simplicity, let's assume we're dealing with insertions/deletions
    # Check if insertion happened at pos
    if len(s_in) < len(s_out):
        # Insertion case
        old_sub = ""
        new_sub = s_out[pos]
        return old_sub, new_sub, pos
    elif len(s_in) > len(s_out):
        # Deletion case  
        old_sub = s_in[pos]
        new_sub = ""
        return old_sub, new_sub, pos
    else:
        # Substitution case
        old_sub = s_in[pos]
        new_sub = s_out[pos]
        return old_sub, new_sub, pos

# Analyze each changed pair
changed = [(0, 'vecbfz', 'vfdxgbfz'), (1, 'ccfu', 'ggfu'), (3, 'bi', 'bd'), (4, 'hyvk', 'huyvk')]

for idx, inp, outp in changed:
    old, new, pos = find_minimal_edit(inp, outp)
    print(f"Pair {idx}: '{inp}' -> '{outp}' | Change at pos {pos}: '{old}' -> '{new}'")

